/// Result from a MAVLink command (MAV_CMD)
public enum MavResult {
    /// Command is valid (is supported and has valid parameters), and was executed.
    public static let accepted: UInt8 = 0
    /// Command is valid, but cannot be executed at this time. This is used to
    /// indicate a problem that should be fixed just by waiting (e.g. a state
    /// machine is busy, can't arm because have not got GPS lock, etc.). Retrying
    /// later should work.
    public static let temporarilyRejected: UInt8 = 1
    /// Command is invalid (is supported but has invalid parameters). Retrying same
    /// command and parameters will not work.
    public static let denied: UInt8 = 2
    /// Command is not supported (unknown).
    public static let unsupported: UInt8 = 3
    /// Command is valid, but execution has failed. This is used to indicate any
    /// non-temporary or unexpected problem, i.e. any problem that must be fixed
    /// before the command can succeed/be retried. For example, attempting to write
    /// a file when out of memory, attempting to arm when sensors are not
    /// calibrated, etc.
    public static let failed: UInt8 = 4
    /// Command is valid and is being executed. This will be followed by further
    /// progress updates, i.e. the component may send further COMMAND_ACK messages
    /// with result MAV_RESULT_IN_PROGRESS (at a rate decided by the
    /// implementation), and must terminate by sending a COMMAND_ACK message with
    /// final result of the operation. The COMMAND_ACK.progress field can be used to
    /// indicate the progress of the operation. There is no need for the sender to
    /// retry the command, but if done during execution, the component will return
    /// MAV_RESULT_IN_PROGRESS with an updated progress.
    public static let inProgress: UInt8 = 5
    /// Command is only accepted when sent as a COMMAND_LONG.
    public static let commandLongOnly: UInt8 = 7
    /// Command is only accepted when sent as a COMMAND_INT.
    public static let commandIntOnly: UInt8 = 8

    /// The name the definitions give a value, or nil for one they do not.
    public static func name(_ value: some BinaryInteger) -> String? {
        names[UInt32(truncatingIfNeeded: value)]
    }

    private static let names: [UInt32: String] = [
        0: "MAV_RESULT_ACCEPTED",
        1: "MAV_RESULT_TEMPORARILY_REJECTED",
        2: "MAV_RESULT_DENIED",
        3: "MAV_RESULT_UNSUPPORTED",
        4: "MAV_RESULT_FAILED",
        5: "MAV_RESULT_IN_PROGRESS",
        7: "MAV_RESULT_COMMAND_LONG_ONLY",
        8: "MAV_RESULT_COMMAND_INT_ONLY",
    ]
}

/// Coordinate frames used by MAVLink. Not all frames are supported by all
/// commands, messages, or vehicles. Global frames use the following naming
/// conventions: - "GLOBAL": Global coordinate frame with WGS84
/// latitude/longitude and altitude positive over mean sea level (MSL) by
/// default. The following modifiers may be used with "GLOBAL": -
/// "RELATIVE_ALT": Altitude is relative to the vehicle home position rather
/// than MSL. - "TERRAIN_ALT": Altitude is relative to ground level rather than
/// MSL. - "INT": Latitude/longitude (in degrees) are scaled by multiplying by
/// 1E7. Local frames use the following naming conventions: - "LOCAL": Origin of
/// local frame is fixed relative to earth. Unless otherwise specified this
/// origin is the origin of the vehicle position-estimator ("EKF"). - "BODY":
/// Origin of local frame travels with the vehicle. NOTE, "BODY" does NOT
/// indicate alignment of frame axis with vehicle attitude. - "OFFSET":
/// Deprecated synonym for "BODY" (origin travels with the vehicle). Not to be
/// used for new frames. Some deprecated frames do not follow these conventions
/// (e.g. MAV_FRAME_BODY_NED and MAV_FRAME_BODY_OFFSET_NED).
public enum MavFrame {
    /// Global (WGS84) coordinate frame + altitude relative to mean sea level (MSL).
    public static let global: UInt8 = 0
    /// NED local tangent frame (x: North, y: East, z: Down) with origin fixed
    /// relative to earth.
    public static let localNed: UInt8 = 1
    /// NOT a coordinate frame, indicates a mission command.
    public static let mission: UInt8 = 2
    /// Global (WGS84) coordinate frame + altitude relative to the home position.
    public static let globalRelativeAlt: UInt8 = 3
    /// ENU local tangent frame (x: East, y: North, z: Up) with origin fixed
    /// relative to earth.
    public static let localEnu: UInt8 = 4
    /// Global (WGS84) coordinate frame (scaled) + altitude relative to mean sea
    /// level (MSL).
    public static let globalInt: UInt8 = 5
    /// Global (WGS84) coordinate frame (scaled) + altitude relative to the home
    /// position.
    public static let globalRelativeAltInt: UInt8 = 6
    /// NED local tangent frame (x: North, y: East, z: Down) with origin that
    /// travels with the vehicle.
    public static let localOffsetNed: UInt8 = 7
    /// Same as MAV_FRAME_LOCAL_NED when used to represent position values. Same as
    /// MAV_FRAME_BODY_FRD when used with velocity/acceleration values.
    public static let bodyNed: UInt8 = 8
    /// This is the same as MAV_FRAME_BODY_FRD.
    public static let bodyOffsetNed: UInt8 = 9
    /// Global (WGS84) coordinate frame with AGL altitude (altitude at ground
    /// level).
    public static let globalTerrainAlt: UInt8 = 10
    /// Global (WGS84) coordinate frame (scaled) with AGL altitude (altitude at
    /// ground level).
    public static let globalTerrainAltInt: UInt8 = 11
    /// FRD local frame aligned to the vehicle's attitude (x: Forward, y: Right, z:
    /// Down) with an origin that travels with vehicle.
    public static let bodyFrd: UInt8 = 12
    /// MAV_FRAME_BODY_FLU - Body fixed frame of reference, Z-up (x: Forward, y:
    /// Left, z: Up).
    public static let reserved13: UInt8 = 13
    /// MAV_FRAME_MOCAP_NED - Odometry local coordinate frame of data given by a
    /// motion capture system, Z-down (x: North, y: East, z: Down).
    public static let reserved14: UInt8 = 14
    /// MAV_FRAME_MOCAP_ENU - Odometry local coordinate frame of data given by a
    /// motion capture system, Z-up (x: East, y: North, z: Up).
    public static let reserved15: UInt8 = 15
    /// MAV_FRAME_VISION_NED - Odometry local coordinate frame of data given by a
    /// vision estimation system, Z-down (x: North, y: East, z: Down).
    public static let reserved16: UInt8 = 16
    /// MAV_FRAME_VISION_ENU - Odometry local coordinate frame of data given by a
    /// vision estimation system, Z-up (x: East, y: North, z: Up).
    public static let reserved17: UInt8 = 17
    /// MAV_FRAME_ESTIM_NED - Odometry local coordinate frame of data given by an
    /// estimator running onboard the vehicle, Z-down (x: North, y: East, z: Down).
    public static let reserved18: UInt8 = 18
    /// MAV_FRAME_ESTIM_ENU - Odometry local coordinate frame of data given by an
    /// estimator running onboard the vehicle, Z-up (x: East, y: North, z: Up).
    public static let reserved19: UInt8 = 19
    /// FRD local tangent frame (x: Forward, y: Right, z: Down) with origin fixed
    /// relative to earth. The forward axis is aligned to the front of the vehicle
    /// in the horizontal plane.
    public static let localFrd: UInt8 = 20
    /// FLU local tangent frame (x: Forward, y: Left, z: Up) with origin fixed
    /// relative to earth. The forward axis is aligned to the front of the vehicle
    /// in the horizontal plane.
    public static let localFlu: UInt8 = 21

    /// The name the definitions give a value, or nil for one they do not.
    public static func name(_ value: some BinaryInteger) -> String? {
        names[UInt32(truncatingIfNeeded: value)]
    }

    private static let names: [UInt32: String] = [
        0: "MAV_FRAME_GLOBAL",
        1: "MAV_FRAME_LOCAL_NED",
        2: "MAV_FRAME_MISSION",
        3: "MAV_FRAME_GLOBAL_RELATIVE_ALT",
        4: "MAV_FRAME_LOCAL_ENU",
        5: "MAV_FRAME_GLOBAL_INT",
        6: "MAV_FRAME_GLOBAL_RELATIVE_ALT_INT",
        7: "MAV_FRAME_LOCAL_OFFSET_NED",
        8: "MAV_FRAME_BODY_NED",
        9: "MAV_FRAME_BODY_OFFSET_NED",
        10: "MAV_FRAME_GLOBAL_TERRAIN_ALT",
