/// Indicates the severity level, generally used for status messages to indicate
/// their relative urgency. Based on RFC-5424 using expanded definitions at:
/// http://www.kiwisyslog.com/kb/info:-syslog-message-levels/.
public enum MavSeverity {
    /// System is unusable. This is a "panic" condition.
    public static let emergency: UInt8 = 0
    /// Action should be taken immediately. Indicates error in non-critical systems.
    public static let alert: UInt8 = 1
    /// Action must be taken immediately. Indicates failure in a primary system.
    public static let critical: UInt8 = 2
    /// Indicates an error in secondary/redundant systems.
    public static let error: UInt8 = 3
    /// Indicates about a possible future error if this is not resolved within a
    /// given timeframe. Example would be a low battery warning.
    public static let warning: UInt8 = 4
    /// An unusual event has occurred, though not an error condition. This should be
    /// investigated for the root cause.
    public static let notice: UInt8 = 5
    /// Normal operational messages. Useful for logging. No action is required for
    /// these messages.
    public static let info: UInt8 = 6
    /// Useful non-operational messages that can assist in debugging. These should
    /// not occur during normal operation.
    public static let debug: UInt8 = 7

    /// The name the definitions give a value, or nil for one they do not.
    public static func name(_ value: some BinaryInteger) -> String? {
        names[UInt32(truncatingIfNeeded: value)]
    }

    private static let names: [UInt32: String] = [
        0: "MAV_SEVERITY_EMERGENCY",
        1: "MAV_SEVERITY_ALERT",
        2: "MAV_SEVERITY_CRITICAL",
        3: "MAV_SEVERITY_ERROR",
        4: "MAV_SEVERITY_WARNING",
        5: "MAV_SEVERITY_NOTICE",
        6: "MAV_SEVERITY_INFO",
        7: "MAV_SEVERITY_DEBUG",
    ]
}

