/// These encode the sensors whose status is sent as part of the SYS_STATUS
/// message.
public enum MavSysStatusSensor {
    /// 0x01 3D gyro
    public static let sensor3dGyro: UInt32 = 1
    /// 0x02 3D accelerometer
    public static let sensor3dAccel: UInt32 = 2
    /// 0x04 3D magnetometer
    public static let sensor3dMag: UInt32 = 4
    /// 0x08 absolute pressure
    public static let sensorAbsolutePressure: UInt32 = 8
    /// 0x10 differential pressure
    public static let sensorDifferentialPressure: UInt32 = 16
    /// 0x20 GPS
    public static let sensorGps: UInt32 = 32
    /// 0x40 optical flow
    public static let sensorOpticalFlow: UInt32 = 64
    /// 0x80 computer vision position
    public static let sensorVisionPosition: UInt32 = 128
    /// 0x100 laser based position
    public static let sensorLaserPosition: UInt32 = 256
    /// 0x200 external ground truth (Vicon or Leica)
    public static let sensorExternalGroundTruth: UInt32 = 512
    /// 0x400 3D angular rate control
    public static let sensorAngularRateControl: UInt32 = 1024
    /// 0x800 attitude stabilization
    public static let sensorAttitudeStabilization: UInt32 = 2048
    /// 0x1000 yaw position
    public static let sensorYawPosition: UInt32 = 4096
    /// 0x2000 z/altitude control
    public static let sensorZAltitudeControl: UInt32 = 8192
    /// 0x4000 x/y position control
    public static let sensorXyPositionControl: UInt32 = 16384
    /// 0x8000 motor outputs / control
    public static let sensorMotorOutputs: UInt32 = 32768
    /// 0x10000 RC receiver
    public static let sensorRcReceiver: UInt32 = 65536
    /// 0x20000 2nd 3D gyro
    public static let sensor3dGyro2: UInt32 = 131072
    /// 0x40000 2nd 3D accelerometer
    public static let sensor3dAccel2: UInt32 = 262144
    /// 0x80000 2nd 3D magnetometer
    public static let sensor3dMag2: UInt32 = 524288
    /// 0x100000 geofence
    public static let geofence: UInt32 = 1048576
    /// 0x200000 AHRS subsystem health
    public static let ahrs: UInt32 = 2097152
    /// 0x400000 Terrain subsystem health
    public static let terrain: UInt32 = 4194304
    /// 0x800000 Motors are reversed
    public static let reverseMotor: UInt32 = 8388608
    /// 0x1000000 Logging
    public static let logging: UInt32 = 16777216
    /// 0x2000000 Battery
    public static let sensorBattery: UInt32 = 33554432
    /// 0x4000000 Proximity
    public static let sensorProximity: UInt32 = 67108864
    /// 0x8000000 Satellite Communication
    public static let sensorSatcom: UInt32 = 134217728
    /// 0x10000000 pre-arm check status. Always healthy when armed
    public static let prearmCheck: UInt32 = 268435456
    /// 0x20000000 Avoidance/collision prevention
    public static let obstacleAvoidance: UInt32 = 536870912
    /// 0x40000000 propulsion (actuator, esc, motor or propellor)
    public static let sensorPropulsion: UInt32 = 1073741824

    /// The name the definitions give a value, or nil for one they do not.
    public static func name(_ value: some BinaryInteger) -> String? {
        names[UInt32(truncatingIfNeeded: value)]
    }

